-- Island Dark: derived from JetBrains' Islands Dark scheme (the author's own export, parent Darcula).
-- Colours come from lua/island/palette.lua, generated by tools/icls2nvim.py.
vim.cmd("highlight clear")
if vim.fn.exists("syntax_on") == 1 then
  vim.cmd("syntax reset")
end
vim.o.background = "dark"
vim.o.termguicolors = true
vim.g.colors_name = "island-dark"
require("island").setup()
